    assert active_route.deprecated_at is None


def test_openapi_schema_has_deprecated_at_extension() -> None:
    response = client.get("/openapi.json")
    assert response.status_code == 200
    schema = response.json()

    items_get = schema["paths"]["/items"]["get"]
    assert items_get["deprecated"] is True
    assert items_get["x-deprecated-at"] == "2025-01-01"

    active_get = schema["paths"]["/active"]["get"]
    assert "deprecated" not in active_get
    assert "x-deprecated-at" not in active_get


def test_endpoint_still_callable() -> None:
    response = client.get("/items")
    assert response.status_code == 200
    assert response.json() == {"name": "Foo"}

