from fastapi import FastAPI
from fastapi.testclient import TestClient

app = FastAPI()


@app.get("/items", deprecated_at="2025-01-01")
def read_items() -> dict[str, str]:
    return {"name": "Foo"}


@app.get("/active")
def read_active() -> dict[str, str]:
    return {"name": "Bar"}


client = TestClient(app)


def test_deprecated_at_implies_deprecated() -> None:
    """``deprecated_at`` should mark the route as deprecated automatically."""
    assert app.routes[0].deprecated is True  # type: ignore[attr-defined]
    assert app.routes[0].deprecated_at == "2025-01-01"  # type: ignore[attr-defined]


def test_active_route_is_not_deprecated() -> None:
    """Routes without ``deprecated_at`` should remain non-deprecated."""
    assert app.routes[1].deprecated is None  # type: ignore[attr-defined]
    assert app.routes[1].deprecated_at is None  # type: ignore[attr-defined]


def test_openapi_schema_has_deprecated_at_extension() -> None:
    response = client.get("/openapi.json")
    assert response.status_code == 200
    schema = response.json()

    items_get = schema["paths"]["/items"]["get"]
    assert items_get["deprecated"] is True
    assert items_get["x-deprecated-at"] == "2025-01-01"

    active_get = schema["paths"]["/active"]["get"]
    assert "deprecated" not in active_get
    assert "x-deprecated-at" not in active_get


def test_endpoint_still_callable() -> None:
    response = client.get("/items")
    assert response.status_code == 200
    assert response.json() == {"name": "Foo"}

